from typing import List, Dict
from decimal import Decimal

class PricingService:
    def __init__(self, db_session):
        self.db = db_session

    def get_base_price(self, tier_id: str) -> Decimal:
        """Fetches base price for a given tier from the database."""
        row = self.db.execute(
            "SELECT price FROM pricing_tiers WHERE id = :id",
            {"id": tier_id}
        ).fetchone()
        return Decimal(row['price']) if row else Decimal('0.00')

    def list_available_tiers(self) -> List[Dict]:
        """Returns all tiers currently marked as active in the database."""
        rows = self.db.execute(
            "SELECT id, name, price, features FROM pricing_tiers WHERE status = 'active'"
        ).fetchall()
        return [dict(row) for row in rows]

def format_currency(amount: Decimal) -> str:
    return f"${amount:,.2f}"

def calculate_tax(amount: Decimal, region: str) -> Decimal:
    # Placeholder for regional tax calculation logic
    tax_rates = {"US": Decimal("0.00"), "EU": Decimal("0.20")}
    rate = tax_rates.get(region, Decimal("0.00"))
    return (amount * rate).quantize(Decimal("0.01"))
